export function getLanguage(e){if("system"===e){let t=navigator.language.slice(0,2);return dictionary[t]?t:"en"}return dictionary[e]?e:"en"}
export function applyTranslations(e){let t=dictionary[e];document.querySelectorAll("[data-i18n]").forEach(e=>{let n=e.getAttribute("data-i18n");t[n]&&(e.textContent=t[n])})}
export function getTranslation(e,t){return dictionary[e]?.[t]||dictionary.en[t]||t}